from typing import List
from collections import deque
from functools import lru_cache


def max_knight_moves(kx: int, ky: int, positions: List[List[int]]) -> int:
    """
    On a 50x50 chessboard, a knight captures all listed pawns in an alternating
    max/min order. Return the optimal total number of knight moves.
    """
    points = [(kx, ky)] + [(x, y) for x, y in positions]
    count = len(points)
    distances = [[0] * count for _ in range(count)]
    moves = ((1, 2), (1, -2), (-1, 2), (-1, -2),
             (2, 1), (2, -1), (-2, 1), (-2, -1))

    # Compute exact shortest-path distances on the bounded 50x50 board.
    for source_index, (sx, sy) in enumerate(points):
        dist = [[-1] * 50 for _ in range(50)]
        dist[sx][sy] = 0
        queue = deque([(sx, sy)])
        while queue:
            x, y = queue.popleft()
            for dx, dy in moves:
                nx, ny = x + dx, y + dy
                if 0 <= nx < 50 and 0 <= ny < 50 and dist[nx][ny] == -1:
                    dist[nx][ny] = dist[x][y] + 1
                    queue.append((nx, ny))
        for target_index, (tx, ty) in enumerate(points):
            distances[source_index][target_index] = dist[tx][ty]

    full_mask = (1 << len(positions)) - 1

    @lru_cache(maxsize=None)
    def play(mask: int, current: int) -> int:
        if mask == full_mask:
            return 0
        # Alice moves when an even number of pawns have already been taken.
        alice_turn = mask.bit_count() % 2 == 0
        best = None
        for pawn in range(len(positions)):
            bit = 1 << pawn
            if not mask & bit:
                score = distances[current][pawn + 1] + play(mask | bit, pawn + 1)
                if best is None or (score > best if alice_turn else score < best):
                    best = score
        return best if best is not None else 0

    return play(0, 0)

