MOD = 10**9 + 7


def count_good_integers(num1: str, num2: str, min_sum: int, max_sum: int) -> int:
    """Count integers in the inclusive range whose digit sum is in the requested interval.

    The result is returned modulo 10^9 + 7.
    """
    def count_up_to(bound: str) -> int:
        # dp[tight][sum] counts prefixes that are equal to / below the bound prefix.
        dp = [0] * (max_sum + 1)
        dp[0] = 1
        tight = [0] * (max_sum + 1)
        tight[0] = 1

        for ch in bound:
            limit = int(ch)
            next_dp = [0] * (max_sum + 1)
            next_tight = [0] * (max_sum + 1)

            # Prefixes already below the bound can use any next digit.
            for total, ways in enumerate(dp):
                if ways:
                    for digit in range(10):
                        new_total = total + digit
                        if new_total <= max_sum:
                            next_dp[new_total] = (next_dp[new_total] + ways) % MOD

            # Prefixes equal to the bound can either remain equal or become smaller.
            for total, ways in enumerate(tight):
                if not ways:
                    continue
                for digit in range(limit + 1):
                    new_total = total + digit
                    if new_total > max_sum:
                        continue
                    if digit == limit:
                        next_tight[new_total] = (next_tight[new_total] + ways) % MOD
                    else:
                        next_dp[new_total] = (next_dp[new_total] + ways) % MOD

            dp, tight = next_dp, next_tight

        return sum(dp[min_sum:]) .__add__(sum(tight[min_sum:])) % MOD

    def decrement(value: str) -> str | None:
        digits = list(value)
        i = len(digits) - 1
        while i >= 0 and digits[i] == "0":
            digits[i] = "9"
            i -= 1
        if i < 0:
            return None
        digits[i] = str(int(digits[i]) - 1)
        result = "".join(digits).lstrip("0")
        return result or "0"

    before = decrement(num1)
    lower_count = count_up_to(before) if before is not None else 0
    return (count_up_to(num2) - lower_count) % MOD

from functools import lru_cache


def count_beautiful_integers(low: int, high: int, k: int) -> int:
    """Count integers in [low, high] with equally many even and odd digits
    that are divisible by k.
    """

    def count_at_most(limit: int) -> int:
        if limit <= 0:
            return 0
        digits = tuple(map(int, str(limit)))

        @lru_cache(None)
        def dp(pos: int, balance: int, remainder: int, started: bool, tight: bool) -> int:
            if pos == len(digits):
                return int(started and balance == 0 and remainder == 0)

            upper = digits[pos] if tight else 9
            total = 0
            for digit in range(upper + 1):
                next_tight = tight and digit == upper
                if not started and digit == 0:
                    total += dp(pos + 1, balance, remainder, False, next_tight)
                else:
                    next_balance = balance + (1 if digit % 2 == 0 else -1)
                    next_remainder = (remainder * 10 + digit) % k
                    total += dp(
                        pos + 1,
                        next_balance,
                        next_remainder,
                        True,
                        next_tight,
                    )
            return total

        return dp(0, 0, 0, False, True)

    return count_at_most(high) - count_at_most(low - 1)

