from typing import List
from functools import lru_cache


def max_knight_moves(kx: int, ky: int, positions: List[List[int]]) -> int:
    """Return the optimal minimax total of shortest knight distances for all pawns."""
    points = [(kx, ky)] + [(x, y) for x, y in positions]
    n = len(points)
    distances = [[0] * n for _ in range(n)]

    def knight_distance(x1: int, y1: int, x2: int, y2: int) -> int:
        dx, dy = sorted((abs(x1 - x2), abs(y1 - y2)), reverse=True)
        if (dx, dy) == (1, 0):
            return 3
        if (dx, dy) == (1, 1):
            return 4
        if (dx, dy) == (2, 2):
            return 4
        d = max((dx + 1) // 2, (dx + dy + 2) // 3)
        if (d + dx + dy) % 2:
            d += 1
        return d

    for i, (x1, y1) in enumerate(points):
        for j, (x2, y2) in enumerate(points):
            distances[i][j] = knight_distance(x1, y1, x2, y2)

    full_mask = (1 << len(positions)) - 1

    @lru_cache(None)
    def play(mask: int, current: int) -> int:
        if mask == full_mask:
            return 0
        maximize = mask.bit_count() % 2 == 0
        best = None
        for pawn in range(len(positions)):
            bit = 1 << pawn
            if not mask & bit:
                value = distances[current][pawn + 1] + play(mask | bit, pawn + 1)
                if best is None or (value > best if maximize else value < best):
                    best = value
        return best

    return play(0, 0)

