MOD = 998244353


def sum_of_scores(n: int, m: int) -> int:
    """Calculate the sum of divisor counts over all sequences of lengths 1..n."""
    if m == 1:
        return n % MOD

    # In tau(product), expand each factor (1 + total exponent of p).
    # For a chosen set of primes, assigning each prime to a sequence position
    # groups the primes into blocks that share a position.
    primes = [p for p in (2, 3, 5, 7, 11, 13) if p <= m]
    pcount = len(primes)
    size = 1 << pcount

    # c[mask] = sum_{a=1}^m product_{p in mask} v_p(a).
    c = [0] * size
    for a in range(1, m + 1):
        exponents = []
        for p in primes:
            e = 0
            value = a
            while value % p == 0:
                value //= p
                e += 1
            exponents.append(e)
        products = [1] * size
        for mask in range(1, size):
            bit = mask & -mask
            j = bit.bit_length() - 1
            products[mask] = products[mask ^ bit] * exponents[j]
        for mask in range(1, size):
            c[mask] += products[mask]

    # dp[mask][r] sums products of c(block) over partitions into r blocks.
    max_blocks = pcount
    dp = [[0] * (max_blocks + 1) for _ in range(size)]
    dp[0][0] = 1
    for mask in range(1, size):
        first = mask & -mask
        block = mask
        while block:
            if block & first:
                rest = mask ^ block
                for r in range(1, max_blocks + 1):
                    dp[mask][r] = (dp[mask][r] + c[block] * dp[rest][r - 1]) % MOD
            block = (block - 1) & mask

    coeff = [0] * (max_blocks + 1)
    coeff[0] = 1  # empty selected-prime set
    for mask in range(1, size):
        for r in range(1, max_blocks + 1):
            coeff[r] = (coeff[r] + dp[mask][r]) % MOD

    # Track q_r(k)=(k)_r*m^k and their prefix sums under k -> k+1.
    # q'_r = m * (q_r + r*q_{r-1}).
    dim = max_blocks + 1
    total_dim = 2 * dim
    mat = [[0] * total_dim for _ in range(total_dim)]
    for r in range(dim):
        mat[r][r] = m % MOD
        if r:
            mat[r][r - 1] = (m * r) % MOD
        mat[dim + r][r] = mat[r][r]
        if r:
            mat[dim + r][r - 1] = mat[r][r - 1]
        mat[dim + r][dim + r] = 1

    def multiply(a, b):
        out = [[0] * total_dim for _ in range(total_dim)]
        for i in range(total_dim):
            for k in range(total_dim):
                if a[i][k]:
                    aik = a[i][k]
                    for j in range(total_dim):
                        if b[k][j]:
                            out[i][j] = (out[i][j] + aik * b[k][j]) % MOD
        return out

    def apply(a, v):
        return [
            sum(a[i][j] * v[j] for j in range(total_dim)) % MOD
            for i in range(total_dim)
        ]

    power = mat
    exponent = n
    vector = [0] * total_dim
    vector[0] = 1  # q_0(0)
    vector[dim] = 1  # prefix sum at k=0
    while exponent:
        if exponent & 1:
            vector = apply(power, vector)
        exponent >>= 1
        if exponent:
            power = multiply(power, power)

    answer = coeff[0] * (vector[dim] - 1) % MOD
    inv_m = pow(m, MOD - 2, MOD)
    inv_power = 1
    for r in range(1, dim):
        inv_power = inv_power * inv_m % MOD
        moment_sum = vector[dim + r] * inv_power % MOD
        answer = (answer + coeff[r] * moment_sum) % MOD
    return answer

from typing import List, Tuple


def min_sensor_cost(n: int, sections: List[int], sensor1: Tuple[int, int, int], sensor2: Tuple[int, int, int]) -> int:
    """Find the minimum cost to monitor all sections with the available sensors.

    Sensors are assigned to sections, may overlap, and their total counts across
    all sections may not exceed the respective inventory limits.
    """
    l1, c1, k1 = sensor1
    l2, c2, k2 = sensor2

    if n == 0:
        return 0
    if l1 <= 0 or l2 <= 0:
        return -1

    # dp[(a, b)] is the least cost after processing some sections with a
    # type-1 and b type-2 sensors.
    dp = {(0, 0): 0}
    for length in sections[:n]:
        options = []
        # For each possible number of type-1 sensors, the least number of
        # type-2 sensors needed is sufficient because all costs are positive.
        for a in range(min(k1, (length + l1 - 1) // l1) + 1):
            remaining = length - a * l1
            b = 0 if remaining <= 0 else (remaining + l2 - 1) // l2
            if b <= k2:
                options.append((a, b, a * c1 + b * c2))
        if not options:
            return -1

        next_dp = {}
        for (used1, used2), cost in dp.items():
            for a, b, extra in options:
                total1, total2 = used1 + a, used2 + b
                if total1 <= k1 and total2 <= k2:
                    key = (total1, total2)
                    value = cost + extra
                    if value < next_dp.get(key, float("inf")):
                        next_dp[key] = value
        if not next_dp:
            return -1

        # Remove states that use at least as many sensors of both types and
        # cost at least as much as another state.
        ordered = sorted(next_dp.items(), key=lambda item: (item[0][0], item[0][1], item[1]))
        kept = {}
        for (used1, used2), cost in ordered:
            dominated = False
            for (other1, other2), other_cost in kept.items():
                if other1 <= used1 and other2 <= used2 and other_cost <= cost:
                    dominated = True
                    break
            if not dominated:
                kept[(used1, used2)] = cost
        dp = kept

    return min(dp.values()) if dp else -1

