from collections import deque


def min_operations_to_rearrange(n: int, s: str, t: str) -> int:
    """Given two strings of stones, return the minimum rearrangement operations.

    There are n stones in the first n cells and two empty cells after them.
    An operation moves an adjacent pair of stones, in their original order,
    into the two currently empty cells. The source cells become the new empty
    cells. Return -1 when the target arrangement cannot be reached.
    """
    if len(s) != n or len(t) != n or s.count("B") != t.count("B"):
        return -1

    start = s + ".."
    goal = t + ".."
    if start == goal:
        return 0

    def neighbors(state):
        holes = [i for i, value in enumerate(state) if value == "."]
        left_hole, right_hole = holes
        for i in range(n + 1):
            first, second = state[i], state[i + 1]
            if first == "." or second == ".":
                continue
            nxt = list(state)
            nxt[i] = nxt[i + 1] = "."
            nxt[left_hole] = first
            nxt[right_hole] = second
            yield "".join(nxt)

    # Bidirectional BFS keeps the search shallow while preserving exact
    # shortest-path distances in this unweighted state graph.
    front_a, dist_a = {start: 0}, {start: 0}
    front_b, dist_b = {goal: 0}, {goal: 0}

    while front_a and front_b:
        if len(front_a) > len(front_b):
            front_a, front_b = front_b, front_a
            dist_a, dist_b = dist_b, dist_a

        next_front = {}
        for state, distance in front_a.items():
            for nxt in neighbors(state):
                if nxt in dist_a:
                    continue
                next_distance = distance + 1
                if nxt in dist_b:
                    return next_distance + dist_b[nxt]
                dist_a[nxt] = next_distance
                next_front[nxt] = next_distance
        front_a = next_front

    return -1

from bisect import bisect_right
from functools import lru_cache
from math import isqrt


_MAX_N = 10**18


def _integer_root(n: int, exponent: int) -> int:
    """Return floor(n ** (1 / exponent)) using integer arithmetic."""
    low, high = 1, 1 << ((n.bit_length() + exponent - 1) // exponent)
    while low < high:
        mid = (low + high + 1) // 2
        if mid**exponent <= n:
            low = mid
        else:
            high = mid - 1
    return low


@lru_cache(maxsize=1)
def _nonsquare_powers():
    # A perfect power that is not a square has an odd factor in its
    # canonical exponent, so it is a^e for some odd e >= 3.
    values = set()
    for exponent in range(3, _MAX_N.bit_length(), 2):
        for base in range(2, _integer_root(_MAX_N, exponent) + 1):
            value = base**exponent
            root = isqrt(value)
            if root * root != value:
                values.add(value)
    return sorted(values)


def count_power_representations(n: int) -> int:
    """ Count how many integers x between 1 and n (inclusive) can be expressed as x = a^b
    where a is a positive integer and b is an integer greater than or equal to 2.

    Args:
        n: The upper bound (1 <= n <= 10^18)

    Returns:
        The count of integers that can be expressed as a^b where b >= 2

    >>> count_power_representations(99)
    12
    >>> count_power_representations(1000000000000000000)
    1001003332
    """
    return isqrt(n) + bisect_right(_nonsquare_powers(), n)

