from functools import lru_cache
from typing import List, Tuple


def can_tile_grid(n: int, h: int, w: int, tiles: List[Tuple[int, int]]) -> bool:
    """ Determine if it's possible to place rectangular tiles on an H×W grid such that:
    - Every cell is covered by exactly one tile
    - Tiles can be rotated (so a 2×3 tile can be placed as 3×2)
    - Some tiles may remain unused
    - Tiles must be aligned with grid cells and cannot extend outside

    Args:
        n: Number of available tiles (1 ≤ n ≤ 7)
        h: Height of the grid (1 ≤ h ≤ 10)
        w: Width of the grid (1 ≤ w ≤ 10)
        tiles: List of (a, b) tuples where tile i has dimensions a×b (1 ≤ a, b ≤ 10)

    Returns:
        True if the grid can be perfectly tiled, False otherwise

    >>> can_tile_grid(5, 5, 5, [(1, 1), (3, 3), (4, 4), (2, 3), (2, 5)])
    True
    >>> can_tile_grid(1, 1, 2, [(2, 3)])
    False
    >>> can_tile_grid(1, 2, 2, [(1, 1)])
    False
    """
    if h <= 0 or w <= 0 or n < 0 or len(tiles) < n:
        return False
    tiles = tiles[:n]
    area = h * w
    tile_areas = [a * b for a, b in tiles]

    # If no subset of available tile areas adds up to the grid area, no tiling
    # can cover the grid.
    possible_areas = {0}
    for tile_area in tile_areas:
        possible_areas |= {x + tile_area for x in tuple(possible_areas)}
    if area not in possible_areas:
        return False

    # Represent occupied cells by bits in a Python integer.
    full = (1 << area) - 1
    placements = []
    for a, b in tiles:
        orientations = {(a, b), (b, a)}
        masks = []
        for ph, pw in orientations:
            if ph <= h and pw <= w:
                for r in range(h - ph + 1):
                    for c in range(w - pw + 1):
                        mask = 0
                        for rr in range(r, r + ph):
                            mask |= ((1 << pw) - 1) << (rr * w + c)
                        masks.append(mask)
        placements.append(tuple(set(masks)))

    subset_area = [0] * (1 << n)
    for mask in range(1, 1 << n):
        bit = mask & -mask
        subset_area[mask] = subset_area[mask ^ bit] + tile_areas[bit.bit_length() - 1]

    @lru_cache(maxsize=None)
    def search(occupied: int, used: int) -> bool:
        if occupied == full:
            return True

        empty_count = area - occupied.bit_count()
        # At least one subset of the unused tiles must have exactly the area
        # left to cover.
        remaining = ((1 << n) - 1) ^ used
        sub = remaining
        area_possible = False
        while True:
            if subset_area[sub] == empty_count:
                area_possible = True
                break
            if sub == 0:
                break
            sub = (sub - 1) & remaining
        if not area_possible:
            return False

        # The first uncovered cell must be the top-left cell of the next tile:
        # any rectangle reaching it from above or from the left would overlap
        # an already occupied cell.
        bitpos = next(i for i in range(area) if not (occupied >> i) & 1)
        r, c = divmod(bitpos, w)
        for i in range(n):
            if (used >> i) & 1:
                continue
            for mask in placements[i]:
                if mask & (1 << bitpos) and not (mask & occupied):
                    if search(occupied | mask, used | (1 << i)):
                        return True
        return False

    return search(0, 0)

from typing import List


MOD = 998244353


def count_strings_by_lcs_length(n: int, m: int, s: str) -> List[int]:
    """Given lowercase string s, count length-m strings by LCS length with s."""
    # The DP row for LCS(s, t) after reading t fully determines its update
    # after one more character. Its entries are the LCS lengths against each
    # prefix of s.
    states = {(0,) * (n + 1): 1}
    letters = set(s)
    absent_count = 26 - len(letters)

    for _ in range(m):
        next_states = {}
        for row, ways in states.items():
            if absent_count:
                next_states[row] = (next_states.get(row, 0) + ways * absent_count) % MOD
            for ch in letters:
                updated = [0] * (n + 1)
                for i in range(1, n + 1):
                    best = row[i]
                    if updated[i - 1] > best:
                        best = updated[i - 1]
                    if s[i - 1] == ch and row[i - 1] + 1 > best:
                        best = row[i - 1] + 1
                    updated[i] = best
                key = tuple(updated)
                next_states[key] = (next_states.get(key, 0) + ways) % MOD
        states = next_states

    result = [0] * (n + 1)
    for row, ways in states.items():
        result[row[n]] = (result[row[n]] + ways) % MOD
    return result

from functools import lru_cache
from typing import List


def tic_tac_toe_winner(grid: List[List[int]]) -> str:
    """Play the modified tic-tac-toe game optimally and return the winner."""
    values = tuple(grid[r][c] for r in range(3) for c in range(3))
    lines = (
        0b000000111, 0b000111000, 0b111000000,
        0b001001001, 0b010010010, 0b100100100,
        0b100010001, 0b001010100,
    )
    full = (1 << 9) - 1
    win_utility = 10**30

    @lru_cache(maxsize=None)
    def play(takahashi: int, aoki: int) -> int:
        # Utility is Takahashi's score margin; a line win dominates any margin.
        occupied = takahashi | aoki
        takahashi_turn = occupied.bit_count() % 2 == 0

        if occupied == full:
            return sum(
                values[i] if takahashi >> i & 1 else -values[i]
                for i in range(9)
            )

        available = full ^ occupied
        best = -win_utility - 1 if takahashi_turn else win_utility + 1
        while available:
            bit = available & -available
            available -= bit
            if takahashi_turn:
                next_t = takahashi | bit
                if any(next_t & line == line for line in lines):
                    outcome = win_utility
                else:
                    outcome = play(next_t, aoki)
                best = max(best, outcome)
            else:
                next_a = aoki | bit
                if any(next_a & line == line for line in lines):
                    outcome = -win_utility
                else:
                    outcome = play(takahashi, next_a)
                best = min(best, outcome)
        return best

    return "Takahashi" if play(0, 0) > 0 else "Aoki"

