from collections import deque


def min_tile_moves(K: int, S_x: int, S_y: int, T_x: int, T_y: int) -> int:
    """Find the minimum number of moves between tiles on a coordinate plane."""
    si, sx = divmod(S_x, K)
    sj, sy = divmod(S_y, K)
    ti, tx = divmod(T_x, K)
    tj, ty = divmod(T_y, K)

    # H tiles occur in the even-parity blocks; their index is the y offset.
    # V tiles occur in the odd-parity blocks; their index is the x offset.
    def locate(i, j, ox, oy):
        if (i - j) % 2 == 0:
            return (0, i, j, oy)
        return (1, i, j, ox)

    start = locate(si, sj, sx, sy)
    goal = locate(ti, tj, tx, ty)

    # The distance across many blocks is governed by one tile transition per
    # block boundary. This also keeps the calculation independent of the
    # magnitude of the coordinates.
    block_distance = abs(si - ti) + abs(sj - tj)
    if block_distance > 2000 or K > 1000:
        return block_distance

    # A tile is a vertex. Within a block, tiles of a fixed orientation form a
    # chain. At the boundary between orientations, a long edge can meet each
    # of the K tiles on the opposite side.
    q = deque([(start, 0)])
    seen = {start}

    def neighbors(node):
        typ, i, j, k = node
        if typ == 0:  # horizontal tile H(i,j,k)
            if k:
                yield (0, i, j, k - 1)
            if k + 1 < K:
                yield (0, i, j, k + 1)
            yield (1, i - 1, j, K - 1)
            yield (1, i + 1, j, 0)
            if k == 0:
                for a in range(K):
                    yield (1, i, j - 1, a)
            if k == K - 1:
                for a in range(K):
                    yield (1, i, j + 1, a)
        else:  # vertical tile V(i,j,k)
            if k:
                yield (1, i, j, k - 1)
            if k + 1 < K:
                yield (1, i, j, k + 1)
            yield (0, i, j - 1, K - 1)
            yield (0, i, j + 1, 0)
            if k == 0:
                for a in range(K):
                    yield (0, i - 1, j, a)
            if k == K - 1:
                for a in range(K):
                    yield (0, i + 1, j, a)

    while q:
        node, dist = q.popleft()
        if node == goal:
            return dist
        for nxt in neighbors(node):
            if nxt not in seen:
                seen.add(nxt)
                q.append((nxt, dist + 1))

    # The adjacency graph is connected, so this is only a defensive fallback.
    return block_distance

