def calculate_black_area_doubled(A: int, B: int, C: int, D: int) -> int:
    """Calculate twice the black-painted area in the AtCoder wallpaper pattern."""
    def clip(poly, bound, keep_le):
        if not poly:
            return []
        out = []
        for p, q in zip(poly, poly[1:] + poly[:1]):
            vp = p[0] + p[1] - bound
            vq = q[0] + q[1] - bound
            inp = vp <= 1e-12 if keep_le else vp >= -1e-12
            inq = vq <= 1e-12 if keep_le else vq >= -1e-12
            if inp:
                out.append(p)
            if inp != inq:
                t = vp / (vp - vq)
                out.append((p[0] + t * (q[0] - p[0]),
                            p[1] + t * (q[1] - p[1])))
        return out

    def area(poly):
        if len(poly) < 3:
            return 0.0
        return abs(sum(p[0] * q[1] - q[0] * p[1]
                       for p, q in zip(poly, poly[1:] + poly[:1]))) / 2

    def partial(x, y):
        # Integrate the pattern over [0,x] x [0,y] within one 2 by 4 period.
        total = 0.0
        for i in range(2):
            for j in range(4):
                x0, x1 = float(i), min(float(i + 1), x)
                y0, y1 = float(j), min(float(j + 1), y)
                if x1 <= x0 or y1 <= y0:
                    continue
                rect = [(x0,y0), (x1,y0), (x1,y1), (x0,y1)]
                cuts = [k for k in range(0, 8, 2) if x0+y0 < k < x1+y1]
                bounds = [x0 + y0] + cuts + [x1 + y1]
                for lo, hi in zip(bounds, bounds[1:]):
                    poly = clip(rect, lo, False)
                    poly = clip(poly, hi, True)
                    if len(poly) < 3:
                        continue
                    cx = sum(p[0] for p in poly) / len(poly)
                    cy = sum(p[1] for p in poly) / len(poly)
                    parity = (int(cx) + int(cy // 2) + int((cx + cy) // 2)) & 1
                    if parity == 0:
                        total += area(poly)
        return int(round(2 * total))

    tile = partial(2.0, 4.0)

    def prefix(x, y):
        q, rx = divmod(x, 2)
        r, ry = divmod(y, 4)
        return (q * r * tile + q * partial(2.0, float(ry))
                + r * partial(float(rx), 4.0)
                + partial(float(rx), float(ry)))

    return prefix(C, D) - prefix(A, D) - prefix(C, B) + prefix(A, B)

def count_paths(H: int, W: int, K: int, grid: list[str]) -> int:
    """Count ordered self-avoiding walks of K moves starting on any empty cell."""
    neighbors = [[] for _ in range(H * W)]
    empty = []
    for r in range(H):
        for c in range(W):
            if grid[r][c] != ".":
                continue
            v = r * W + c
            empty.append(v)
            if r > 0 and grid[r - 1][c] == ".":
                neighbors[v].append(v - W)
            if r + 1 < H and grid[r + 1][c] == ".":
                neighbors[v].append(v + W)
            if c > 0 and grid[r][c - 1] == ".":
                neighbors[v].append(v - 1)
            if c + 1 < W and grid[r][c + 1] == ".":
                neighbors[v].append(v + 1)

    # A bit mask makes the visited-cell check inexpensive, including on 10x10 grids.
    def extend(v: int, remaining: int, visited: int) -> int:
        if remaining == 0:
            return 1
        total = 0
        for nxt in neighbors[v]:
            bit = 1 << nxt
            if not visited & bit:
                total += extend(nxt, remaining - 1, visited | bit)
        return total

    return sum(extend(start, K, 1 << start) for start in empty)

