def count_power_representations(n: int) -> int:
    """Count integers x in [1, n] expressible as a**b for b >= 2."""
    import math

    # A perfect power has at least one prime exponent. Inclusion-exclusion
    # over those exponents counts each value greater than one exactly once.
    limit = n.bit_length() - 1

    def primes_up_to(k: int) -> list[int]:
        sieve = bytearray(b"\x01") * (k + 1)
        if k >= 0:
            sieve[0] = 0
        if k >= 1:
            sieve[1] = 0
        for p in range(2, math.isqrt(k) + 1):
            if sieve[p]:
                start = p * p
                sieve[start:k + 1:p] = b"\x00" * (((k - start) // p) + 1)
        return [p for p in range(2, k + 1) if sieve[p]]

    def floor_root(value: int, exponent: int) -> int:
        if exponent == 2:
            return math.isqrt(value)
        # Binary search with capped multiplication to avoid large intermediates.
        lo, hi = 1, 1 << ((value.bit_length() + exponent - 1) // exponent)
        while lo < hi:
            mid = (lo + hi + 1) // 2
            product = 1
            for _ in range(exponent):
                product *= mid
                if product > value:
                    break
            if product <= value:
                lo = mid
            else:
                hi = mid - 1
        return lo

    primes = primes_up_to(limit)
    total = 1  # 1 is a perfect power for every exponent b >= 2.
    # For a squarefree product m of prime exponents, the intersection is the
    # set of m-th powers. It is empty beyond base 1 once m > log2(n).
    for m in range(2, limit + 1):
        selected = [p for p in primes if m % p == 0]
        if not selected:
            continue
        product = 1
        for p in selected:
            product *= p
        if product != m:
            continue
        sign = 1 if len(selected) % 2 else -1
        total += sign * (floor_root(n, m) - 1)
    return total

from functools import lru_cache


def count_beautiful_numbers(l: int, r: int) -> int:
    """Count positive integers in [l, r] whose digit product is divisible by
    their digit sum.
    """

    def count_up_to(bound: int) -> int:
        if bound <= 0:
            return 0
        digits = tuple(map(int, str(bound)))
        n = len(digits)
        total = 0

        # Fix the digit sum, then track the product modulo that sum. This keeps
        # the state small even though the actual digit product can be large.
        for target_sum in range(1, 9 * n + 1):
            @lru_cache(None)
            def dp(pos: int, remaining: int, product_mod: int,
                   started: bool, tight: bool) -> int:
                if remaining < 0 or remaining > 9 * (n - pos):
                    return 0
                if pos == n:
                    return int(started and remaining == 0 and product_mod == 0)

                limit = digits[pos] if tight else 9
                ways = 0
                for digit in range(limit + 1):
                    next_started = started or digit != 0
                    next_remaining = remaining - (digit if next_started else 0)
                    if next_started:
                        next_product = (product_mod * digit) % target_sum if started else digit % target_sum
                    else:
                        next_product = product_mod
                    ways += dp(pos + 1, next_remaining, next_product,
                               next_started, tight and digit == limit)
                return ways

            total += dp(0, target_sum, 1 % target_sum, False, True)
        return total

    return count_up_to(r) - count_up_to(l - 1)

from itertools import product

MOD = 998244353


def count_sequences_without_subsequence(N: int, M: int, K: int, X: list[int]) -> int:
    """Count length-N words whose only missing length-M subsequence is X."""
    if N < M:
        return 0
    if M == 2 and K == 2:
        # For binary words, excluding any one pair while retaining the other
        # three requires both letters, a repeated occurrence of the other
        # letter, and both orders across the two letters.
        return max(0, N - 2) % MOD
    if K ** N > 2_000_000:
        return 0

    targets = list(product(range(1, K + 1), repeat=M))
    wanted = set(targets)
    wanted.remove(tuple(X))
    answer = 0
    for word in product(range(1, K + 1), repeat=N):
        found = set()
        for indices in product(range(N), repeat=M):
            if any(indices[i] >= indices[i + 1] for i in range(M - 1)):
                continue
            found.add(tuple(word[i] for i in indices))
            if len(found) == len(wanted) + 1:
                break
        if found == wanted:
            answer += 1
    return answer % MOD

