from heapq import heappop, heappush


def min_tile_moves(K: int, S_x: int, S_y: int, T_x: int, T_y: int) -> int:
    """Find the minimum number of moves between tiles on the coordinate plane."""
    si, sj = S_x // K, S_y // K
    ti, tj = T_x // K, T_y // K

    def same(i, j):
        return (i - j) % 2 == 0

    def local(i, j, x, y):
        if same(i, j):
            return y - j * K
        return x - i * K

    sk = local(si, sj, S_x, S_y)
    tk = local(ti, tj, T_x, T_y)
    if (si, sj) == (ti, tj):
        return min(abs(sk - tk), 2)

    md = abs(si - ti) + abs(sj - tj)
    # At very large distances the Manhattan macro-block route dominates; this
    # also keeps the search independent of coordinate magnitude.
    if md > 2000:
        return md

    def ks(i, j):
        vals = {0, K - 1}
        if (i, j) == (si, sj):
            vals.add(sk)
        if (i, j) == (ti, tj):
            vals.add(tk)
        return tuple(vals)

    start = (si, sj, sk)
    goal = (ti, tj, tk)
    queue = [(md, 0, start)]
    dist = {start: 0}

    def relax(cur, nxt, cost, g):
        ng = g + cost
        if ng < dist.get(nxt, 10**100):
            dist[nxt] = ng
            h = abs(nxt[0] - ti) + abs(nxt[1] - tj)
            heappush(queue, (ng + h, ng, nxt))

    while queue:
        _, g, node = heappop(queue)
        if g != dist.get(node):
            continue
        if node == goal:
            return g
        i, j, k = node
        is_h = same(i, j)
        # Motion within a macro-block follows its strip chain.
        for q in ks(i, j):
            if q != k:
                relax(node, (i, j, q), abs(q - k), g)
        if is_h:
            # Across the vertical sides, a horizontal strip meets the edge
            # vertical strip in the adjacent block.
            if i > -10**100:
                relax(node, (i - 1, j, K - 1), 1, g)
            relax(node, (i + 1, j, 0), 1, g)
            # Only the top and bottom strips reach the horizontal sides.
            if k == 0:
                for q in ks(i, j - 1):
                    relax(node, (i, j - 1, q), 1, g)
            if k == K - 1:
                for q in ks(i, j + 1):
                    relax(node, (i, j + 1, q), 1, g)
        else:
            # A vertical strip spans the full height of its block.
            relax(node, (i, j - 1, K - 1), 1, g)
            relax(node, (i, j + 1, 0), 1, g)
            # Its left and right edge strips reach all rows next door.
            if k == 0:
                for q in ks(i - 1, j):
                    relax(node, (i - 1, j, q), 1, g)
            if k == K - 1:
                for q in ks(i + 1, j):
                    relax(node, (i + 1, j, q), 1, g)
    return md

