from heapq import heappop, heappush


def min_tile_moves(K: int, S_x: int, S_y: int, T_x: int, T_y: int) -> int:
    """ Find the minimum number of moves between tiles on a coordinate plane.

    Tiles are placed according to these rules:
    - For integer triple (i, j, k) with 0 <= k < K:
      - If i and j have same parity: tile covers iK <= x <= (i+1)K and jK+k <= y <= jK+k+1
      - If i and j have different parity: tile covers iK+k <= x <= iK+k+1 and jK <= y <= (j+1)K

    Two tiles are adjacent if their edges share a positive-length segment.

    Args:
        K: The tile parameter (2 <= K <= 10^16)
        S_x, S_y: Starting coordinates (tile containing (S_x + 0.5, S_y + 0.5))
        T_x, T_y: Target coordinates (tile containing (T_x + 0.5, T_y + 0.5))

    Returns:
        Minimum number of moves to adjacent tiles needed to go from start to target tile.
    """
    si, sj = S_x // K, S_y // K
    ti, tj = T_x // K, T_y // K

    def horizontal(i, j):
        return (i - j) % 2 == 0

    def local(i, j, x, y):
        return y - j * K if horizontal(i, j) else x - i * K

    sk = local(si, sj, S_x, S_y)
    tk = local(ti, tj, T_x, T_y)
    if (si, sj) == (ti, tj):
        return min(abs(sk - tk), 2)

    macro_distance = abs(si - ti) + abs(sj - tj)
    if macro_distance > 2000:
        return macro_distance

    def strip_indices(i, j):
        # End strips are the only ones that can leave a block in its short
        # direction. Source and target strips can also be useful inside their
        # respective blocks.
        if K <= 200:
            return range(K)
        values = {0, K - 1}
        if (i, j) == (si, sj):
            values.add(sk)
        if (i, j) == (ti, tj):
            values.add(tk)
        return values

    start = (si, sj, sk)
    goal = (ti, tj, tk)
    queue = [(macro_distance, 0, start)]
    distances = {start: 0}

    def relax(nxt, cost, current_cost):
        candidate = current_cost + cost
        if candidate < distances.get(nxt, 10**100):
            distances[nxt] = candidate
            estimate = abs(nxt[0] - ti) + abs(nxt[1] - tj)
            heappush(queue, (candidate + estimate, candidate, nxt))

    while queue:
        _, cost, node = heappop(queue)
        if cost != distances.get(node):
            continue
        if node == goal:
            return cost

        i, j, k = node
        is_horizontal = horizontal(i, j)
        for q in strip_indices(i, j):
            if q != k:
                relax((i, j, q), abs(q - k), cost)

        if is_horizontal:
            # Every horizontal strip touches the end strip in the block to
            # its left or right.
            relax((i - 1, j, K - 1), 1, cost)
            relax((i + 1, j, 0), 1, cost)
            # Only the boundary rows touch blocks above and below.
            if k == 0:
                for q in strip_indices(i, j - 1):
                    relax((i, j - 1, q), 1, cost)
            if k == K - 1:
                for q in strip_indices(i, j + 1):
                    relax((i, j + 1, q), 1, cost)
        else:
            # Every vertical strip spans the full block height.
            relax((i, j - 1, K - 1), 1, cost)
            relax((i, j + 1, 0), 1, cost)
            # Only the boundary columns touch blocks on the sides.
            if k == 0:
                for q in strip_indices(i - 1, j):
                    relax((i - 1, j, q), 1, cost)
            if k == K - 1:
                for q in strip_indices(i + 1, j):
                    relax((i + 1, j, q), 1, cost)
    return macro_distance

def calculate_black_area_doubled(A: int, B: int, C: int, D: int) -> int:
    """Calculate twice the black area in the specified wallpaper rectangle."""
    def axis_parts(lo, hi, period):
        start = lo % period
        length = hi - lo
        first = min(length, period - start)
        parts = []
        if first:
            parts.append((start, start + first))
        length -= first
        full, rem = divmod(length, period)
        if full:
            parts.append((0, period, full))
        if rem:
            parts.append((0, rem))
        return parts

    def parity(x, y):
        return (int(x // 1) + int(y // 2) + int((x + y) // 2)) & 1

    def signed_small(x1, x2, y1, y2):
        low, high = x1 + y1, x2 + y2
        first = (int(low // 2) + 1) * 2
        cuts = [n for n in range(first, int(high // 2) * 2 + 1, 2)
                if low < n < high]
        area = (x2 - x1) * (y2 - y1)
        if not cuts:
            sign = 1 if parity((x1 + x2) / 2, (y1 + y2) / 2) == 0 else -1
            return sign * area
        n = cuts[0]
        poly = [(x1, y1), (x2, y1), (x2, y2), (x1, y2)]
        clipped = []
        for idx, p in enumerate(poly):
            q = poly[(idx + 1) % 4]
            fp, fq = p[0] + p[1] - n, q[0] + q[1] - n
            if fp <= 0:
                clipped.append(p)
            if (fp < 0 < fq) or (fq < 0 < fp):
                t = -fp / (fq - fp)
                clipped.append((p[0] + t * (q[0] - p[0]),
                                p[1] + t * (q[1] - p[1])))
        below = 0.0
        if len(clipped) >= 3:
            below = abs(sum(clipped[k][0] * clipped[(k + 1) % len(clipped)][1]
                            - clipped[(k + 1) % len(clipped)][0] * clipped[k][1]
                            for k in range(len(clipped))) / 2)
        # The lower-left corner is strictly below every internal diagonal.
        below_sign = 1 if parity(x1 + 1e-8, y1 + 1e-8) == 0 else -1
        return below_sign * below - below_sign * (area - below)

    def integrate_piece(x1, x2, y1, y2):
        total = 0.0
        xs = [x1] + [i for i in range(int(x1) + 1, int(x2) + 1) if x1 < i < x2] + [x2]
        ys = [y1] + [i for i in range(int(y1) + 1, int(y2) + 1) if y1 < i < y2] + [y2]
        for xa, xb in zip(xs, xs[1:]):
            for ya, yb in zip(ys, ys[1:]):
                total += signed_small(xa, xb, ya, yb)
        return total

    xp = axis_parts(A, C, 4)
    yp = axis_parts(B, D, 2)
    signed = 0.0
    for xpart in xp:
        x1, x2 = xpart[0], xpart[1]
        xm = xpart[2] if len(xpart) == 3 else 1
        for ypart in yp:
            y1, y2 = ypart[0], ypart[1]
            ym = ypart[2] if len(ypart) == 3 else 1
            signed += xm * ym * integrate_piece(x1, x2, y1, y2)
    return int(round((C - A) * (D - B) + signed))

def calculate_black_area_doubled(A: int, B: int, C: int, D: int) -> int:
    """Calculate twice the black area in the specified wallpaper rectangle."""
    def axis_parts(lo, hi, period):
        start = lo % period
        length = hi - lo
        first = min(length, period - start)
        parts = []
        if first:
            parts.append((start, start + first))
        length -= first
        full, rem = divmod(length, period)
        if full:
            parts.append((0, period, full))
        if rem:
            parts.append((0, rem))
        return parts

    def parity(x, y):
        return (int(x // 1) + int(y // 2) + int((x + y) // 2)) & 1

    def signed_small(x1, x2, y1, y2):
        low, high = x1 + y1, x2 + y2
        first = (int(low // 2) + 1) * 2
        cuts = [n for n in range(first, int(high // 2) * 2 + 1, 2)
                if low < n < high]
        area = (x2 - x1) * (y2 - y1)
        if not cuts:
            sign = 1 if parity((x1 + x2) / 2, (y1 + y2) / 2) == 0 else -1
            return sign * area
        n = cuts[0]
        poly = [(x1, y1), (x2, y1), (x2, y2), (x1, y2)]
        clipped = []
        for idx, p in enumerate(poly):
            q = poly[(idx + 1) % 4]
            fp, fq = p[0] + p[1] - n, q[0] + q[1] - n
            if fp <= 0:
                clipped.append(p)
            if (fp < 0 < fq) or (fq < 0 < fp):
                t = -fp / (fq - fp)
                clipped.append((p[0] + t * (q[0] - p[0]),
                                p[1] + t * (q[1] - p[1])))
        below = 0.0
        if len(clipped) >= 3:
            below = abs(sum(clipped[k][0] * clipped[(k + 1) % len(clipped)][1]
                            - clipped[(k + 1) % len(clipped)][0] * clipped[k][1]
                            for k in range(len(clipped))) / 2)
        below_sign = 1 if parity(x1 + 1e-8, y1 + 1e-8) == 0 else -1
        return below_sign * (2 * below - area)

    def integrate_piece(x1, x2, y1, y2):
        total = 0.0
        xs = [x1] + [i for i in range(int(x1) + 1, int(x2) + 1) if x1 < i < x2] + [x2]
        ys = [y1] + [i for i in range(int(y1) + 1, int(y2) + 1) if y1 < i < y2] + [y2]
        for xa, xb in zip(xs, xs[1:]):
            for ya, yb in zip(ys, ys[1:]):
                total += signed_small(xa, xb, ya, yb)
        return total

    signed_twice = 0
    for xpart in axis_parts(A, C, 4):
        x1, x2 = xpart[0], xpart[1]
        xm = xpart[2] if len(xpart) == 3 else 1
        for ypart in axis_parts(B, D, 2):
            y1, y2 = ypart[0], ypart[1]
            ym = ypart[2] if len(ypart) == 3 else 1
            signed_twice += round(2 * integrate_piece(x1, x2, y1, y2)) * xm * ym
    return (C - A) * (D - B) + signed_twice // 2

from heapq import heappop, heappush


def min_tile_moves(K: int, S_x: int, S_y: int, T_x: int, T_y: int) -> int:
    """Find the minimum number of moves between tiles on the coordinate plane."""
    si, sj = S_x // K, S_y // K
    ti, tj = T_x // K, T_y // K

    def horizontal(i, j):
        return (i - j) % 2 == 0

    def local(i, j, x, y):
        return y - j * K if horizontal(i, j) else x - i * K

    sk = local(si, sj, S_x, S_y)
    tk = local(ti, tj, T_x, T_y)
    if (si, sj) == (ti, tj):
        return min(abs(sk - tk), 2)

    di, dj = ti - si, tj - sj
    macro_distance = abs(di) + abs(dj)
    if macro_distance > 2000:
        # In a long route, each axis transition changes the tile orientation.
        # Alternating axes gives a two-move-per-dominant-axis route.
        return 2 * max(abs(di), abs(dj))

    def strip_indices(i, j):
        if K <= 200:
            return range(K)
        values = {0, K - 1}
        if (i, j) == (si, sj):
            values.add(sk)
        if (i, j) == (ti, tj):
            values.add(tk)
        return values

    start = (si, sj, sk)
    goal = (ti, tj, tk)
    queue = [(macro_distance, 0, start)]
    distances = {start: 0}

    def relax(nxt, cost, current_cost):
        candidate = current_cost + cost
        if candidate < distances.get(nxt, 10**100):
            distances[nxt] = candidate
            estimate = abs(nxt[0] - ti) + abs(nxt[1] - tj)
            heappush(queue, (candidate + estimate, candidate, nxt))

    while queue:
        _, cost, node = heappop(queue)
        if cost != distances.get(node):
            continue
        if node == goal:
            return cost

        i, j, k = node
        if horizontal(i, j):
            for q in strip_indices(i, j):
                if q != k:
                    relax((i, j, q), abs(q - k), cost)
            relax((i - 1, j, K - 1), 1, cost)
            relax((i + 1, j, 0), 1, cost)
            if k == 0:
                for q in strip_indices(i, j - 1):
                    relax((i, j - 1, q), 1, cost)
            if k == K - 1:
                for q in strip_indices(i, j + 1):
                    relax((i, j + 1, q), 1, cost)
        else:
            for q in strip_indices(i, j):
                if q != k:
                    relax((i, j, q), abs(q - k), cost)
            relax((i, j - 1, K - 1), 1, cost)
            relax((i, j + 1, 0), 1, cost)
            if k == 0:
                for q in strip_indices(i - 1, j):
                    relax((i - 1, j, q), 1, cost)
            if k == K - 1:
                for q in strip_indices(i + 1, j):
                    relax((i + 1, j, q), 1, cost)
    return 2 * max(abs(di), abs(dj))

