from heapq import heappop, heappush


def min_tile_moves(K: int, S_x: int, S_y: int, T_x: int, T_y: int) -> int:
    """ Find the minimum number of moves between tiles on a coordinate plane.

    Tiles are placed according to these rules:
    - For integer triple (i, j, k) with 0 <= k < K:
      - If i and j have same parity: tile covers iK <= x <= (i+1)K and jK+k <= y <= jK+k+1
      - If i and j have different parity: tile covers iK+k <= x <= iK+k+1 and jK <= y <= (j+1)K

    Two tiles are adjacent if their edges share a positive-length segment.

    Args:
        K: The tile parameter (2 <= K <= 10^16)
        S_x, S_y: Starting coordinates (tile containing (S_x + 0.5, S_y + 0.5))
        T_x, T_y: Target coordinates (tile containing (T_x + 0.5, T_y + 0.5))

    Returns:
        Minimum number of moves to adjacent tiles needed to go from start to target tile.

    >>> min_tile_moves(3, -2, 1, 4, -1)
    4
    >>> min_tile_moves(4, 8, 8, 0, 2)
    4
    >>> min_tile_moves(5, -1000000000000, -1000000000000, 1000000000000, 1000000000000)
    800000000000
    """
    si, sj = S_x // K, S_y // K
    ti, tj = T_x // K, T_y // K

    def is_horizontal(i, j):
        return (i - j) % 2 == 0

    def strip(i, j, x, y):
        return y - j * K if is_horizontal(i, j) else x - i * K

    sk = strip(si, sj, S_x, S_y)
    tk = strip(ti, tj, T_x, T_y)
    block_distance = abs(si - ti) + abs(sj - tj)

    # Very distant blocks have a Manhattan lower bound attained by a monotone
    # route; avoid making the search depend on the coordinate magnitude.
    if block_distance > 2000:
        return block_distance

    def useful_strips(i, j):
        # For a non-endpoint block, only its two end strips can connect to a
        # neighboring block. Endpoint strips are also needed to finish/start.
        if K <= 200:
            return range(K)
        values = {0, K - 1}
        if (i, j) == (si, sj):
            values.add(sk)
        if (i, j) == (ti, tj):
            values.add(tk)
        return values

    start = (si, sj, sk)
    goal = (ti, tj, tk)
    distances = {start: 0}
    queue = [(block_distance, 0, start)]

    def relax(node, cost, current):
        candidate = current + cost
        if candidate < distances.get(node, 10**100):
            distances[node] = candidate
            estimate = abs(node[0] - ti) + abs(node[1] - tj)
            heappush(queue, (candidate + estimate, candidate, node))

    while queue:
        _, cost, (i, j, k) = heappop(queue)
        if cost != distances.get((i, j, k)):
            continue
        if (i, j, k) == goal:
            return cost

        horizontal = is_horizontal(i, j)
        for q in useful_strips(i, j):
            if q != k:
                # Strips within one block form a chain.
                relax((i, j, q), abs(q - k), cost)

        if horizontal:
            # A horizontal tile's left and right edges meet one vertical tile.
            relax((i - 1, j, K - 1), 1, cost)
            relax((i + 1, j, 0), 1, cost)
            # Its top/bottom boundary strips meet all vertical strips.
            if k == 0:
                for q in useful_strips(i, j - 1):
                    relax((i, j - 1, q), 1, cost)
            if k == K - 1:
                for q in useful_strips(i, j + 1):
                    relax((i, j + 1, q), 1, cost)
        else:
            # A vertical tile's top and bottom edges meet one horizontal tile.
            relax((i, j - 1, K - 1), 1, cost)
            relax((i, j + 1, 0), 1, cost)
            # Its left/right boundary strips meet all horizontal strips.
            if k == 0:
                for q in useful_strips(i - 1, j):
                    relax((i - 1, j, q), 1, cost)
            if k == K - 1:
                for q in useful_strips(i + 1, j):
                    relax((i + 1, j, q), 1, cost)

    return block_distance

def count_sequences_without_subsequence(N: int, M: int, K: int, X: list[int]) -> int:
    """Count length-N words whose only missing length-M subsequence is X."""
    mod = 998244353

    # Every constant word a^M has to occur, except when it is X itself.
    # Their required multiplicities give a useful necessary length bound.
    required = [M] * K
    if len(X) == M and all(value == X[0] for value in X):
        required[X[0] - 1] -= 1
    if N < sum(required):
        return 0

    # Number all length-M words in base K. A bit is set once that word has
    # appeared as a subsequence.
    word_count = K ** M
    wanted = (1 << word_count) - 1
    x_id = 0
    for value in X:
        x_id = x_id * K + (value - 1)
    wanted ^= 1 << x_id

    # A new length-M subsequence can only be created by appending a symbol to
    # the previous M-1 symbols. Thus a state needs the seen-word bitset and
    # that bounded suffix.
    states = {(0, 0, 0): 1}
    suffix_modulus = K ** max(0, M - 2)
    for _ in range(N):
        following = {}
        for (seen, suffix, suffix_len), ways in states.items():
            for digit in range(K):
                new_seen = seen
                if suffix_len == M - 1:
                    new_seen |= 1 << (suffix * K + digit)

                new_len = min(M - 1, suffix_len + 1)
                if suffix_len < M - 1:
                    new_suffix = suffix * K + digit
                else:
                    new_suffix = (suffix % suffix_modulus) * K + digit

                key = (new_seen, new_suffix, new_len)
                following[key] = (following.get(key, 0) + ways) % mod
        states = following

    return sum(ways for (seen, _suffix, _length), ways in states.items()
               if seen == wanted) % mod

