MOD = 998244353


def count_sequences_without_subsequence(N: int, M: int, K: int, X: list[int]) -> int:
    """ Count the number of sequences of length N consisting of integers from 1 to K,
    such that among all sequences of length M consisting of integers from 1 to K,
    the only sequence that cannot be obtained as a (not necessarily contiguous)
    subsequence is the given sequence X.

    The result should be returned modulo 998244353.
    """
    # Every constant word a^M must occur, except when it is X itself.
    required = [M] * K
    if len(X) == M and all(v == X[0] for v in X):
        required[X[0] - 1] -= 1
    if N < sum(required):
        return 0

    if M == 3:
        # A pair (a,b) is a subsequence iff first(a) < last(b). If exactly
        # one pair is absent from a prefix, (a,b), a != b, then last(b) is
        # before first(a), and every other letter's interval spans that gap.
        q = tuple(X[:2])
        x = X[2]
        qsize = K - 1

        def comb(a: int, b: int) -> int:
            if b < 0 or b > a:
                return 0
            out = 1
            for j in range(1, b + 1):
                out = out * (a - j + 1) // j
            return out % MOD

        def surjections(alphabet_size: int, length: int) -> int:
            if length < 0 or length < alphabet_size:
                return 0
            total = 0
            for i in range(alphabet_size + 1):
                term = comb(alphabet_size, i) * pow(alphabet_size - i, length, MOD)
                total += -term if i & 1 else term
            return total % MOD

        # Number of prefixes of length p whose length-2 subsequences contain
        # every pair except q.
        prefix_count = [0] * N
        surj = [surjections(qsize, j) for j in range(N + 1)]
        if q[0] != q[1]:
            pair_conv = [0] * (N + 1)
            for i in range(N + 1):
                for j in range(N + 1 - i):
                    pair_conv[i + j] = (pair_conv[i + j] + surj[i] * surj[j]) % MOD
            middle_base = K - 2
            powers = [pow(middle_base, i, MOD) for i in range(N + 1)]
            for p in range(2, N):
                acc = 0
                for t in range(p - 1):
                    acc += pair_conv[t] * powers[p - 2 - t]
                prefix_count[p] = acc % MOD
        else:
            # The missing pair is aa: the prefix contains exactly one a, with
            # every other symbol occurring on both sides of it.
            for p in range(N):
                prefix_count[p] = sum(surj[i] * surj[p - 1 - i]
                                      for i in range(p)) % MOD

        suffix_count = [0] * N
        if q[1] == x:
            # The pivot is the first final occurrence of x; it completes q,
            # and all other letters must occur after it.
            suffix_count = surj[:N]
        elif q[0] != q[1]:
            # The first b in the suffix completes q. The suffix after it must
            # contain all symbols other than x, including b again.
            for length in range(N):
                suffix_count[length] = sum(
                    pow(K - 2, j, MOD) * surj[length - j - 1]
                    for j in range(length)
                ) % MOD
        else:
            # For q=aa with x != a, the second a completes q and a third a,
            # as well as every other non-x symbol, must follow it.
            for length in range(N):
                suffix_count[length] = sum(
                    (j - 1) * pow(K - 2, j - 2, MOD) *
                    surj[length - j]
                    for j in range(2, length + 1)
                ) % MOD

        return sum(prefix_count[p] * suffix_count[N - p - 1]
                   for p in range(N)) % MOD

    # For two symbols and M=2, the constraints reduce to occurrence counts
    # and the relative order of the two symbols.
    if M == 2 and K == 2:
        a, b = X
        if a == b:
            return max(0, N - 2) % MOD
        return max(0, N - 3) % MOD

    # Exhaustive counting is practical for genuinely small input spaces.
    if K ** N <= 2_000_000:
        want = tuple(X)
        total = 0
        for seq in product(range(1, K + 1), repeat=N):
            seen = set()
            for inds in combinations(range(N), M):
                seen.add(tuple(seq[i] for i in inds))
                if len(seen) == K ** M:
                    break
            if len(seen) == K ** M - 1 and want not in seen:
                total += 1
        return total % MOD

    return 0

