def _prime_data(n):
    """Prime list through sqrt(n), and prime-count tables at floor(n/i)."""
    limit = isqrt(n)
    sieve = bytearray(b"\x01") * (limit + 1)
    if limit >= 0:
        sieve[0] = 0
    if limit >= 1:
        sieve[1] = 0
    for p in range(2, isqrt(limit) + 1):
        if sieve[p]:
            start = p * p
            sieve[start:limit + 1:p] = b"\x00" * (((limit - start) // p) + 1)
    primes = [p for p in range(2, limit + 1) if sieve[p]]

    vals = []
    left = 1
    while left <= n:
        v = n // left
        vals.append(v)
        left = n // v + 1
    pos = {v: i for i, v in enumerate(vals)}
    g0 = [v - 1 for v in vals]
    # Character modulo 3: chi(1)=1, chi(2)=-1, chi(0)=0.
    def chi_prefix(x):
        r = x % 3
        return 1 if r == 1 else 0
    gc = [chi_prefix(v) - 1 for v in vals]

    prime_count = 0
    chi_sum = 0
    for p in primes:
        p2 = p * p
        cp = 1 if p % 3 == 1 else (-1 if p % 3 == 2 else 0)
        for i, v in enumerate(vals):
            if v < p2:
                break
            j = pos[v // p]
            g0[i] -= g0[j] - prime_count
            gc[i] -= cp * (gc[j] - chi_sum)
        prime_count += 1
        chi_sum += cp

    total_pi = {v: g0[i] for i, v in enumerate(vals)}
    # For x>=2, pi_1(x) = (pi(x) + sum_{p<=x} chi(p) - 1) / 2.
    pi1 = {v: (g0[i] + gc[i] - 1) // 2 for i, v in enumerate(vals)}
    # Prefix class counts only needed through sqrt(n).
    pi1_small = [0] * (limit + 1)
    pi3_small = [0] * (limit + 1)
    c1 = c3 = 0
    for x in range(limit + 1):
        if x >= 2 and sieve[x]:
            if x % 3 == 1:
                c1 += 1
            elif x == 3:
                c3 += 1
        pi1_small[x] = c1
        pi3_small[x] = c3
    return primes, total_pi, pi1, pi1_small, pi3_small


def count_good_sequences(N: int, M: int) -> int:
    """Count length-M sequences of positive integers with product <= N and sigma(product) divisible by 3."""
    if N <= 1:
        return 0

    primes, pi, pi1, pi1_small, pi3_small = _prime_data(N)
    root = isqrt(N)
    pindex = {p: i for i, p in enumerate(primes)}
    inv = 1  # keeps local cached arithmetic simple
    choose = [[0] * 35 for _ in range(1)]
    choose[0][0] = 1
    for e in range(1, 35):
        # C(M+e-1,e) modulo MOD, using its short product.
        val = 1
        for j in range(1, e + 1):
            val = val * (M + j - 1) % MOD
            val = val * pow(j, MOD - 2, MOD) % MOD
        choose[0][e] = val
    del choose
    weights = [1] * 35
    for e in range(1, 35):
        weights[e] = weights[e - 1] * (M + e - 1) % MOD * pow(e, MOD - 2, MOD) % MOD

    def prime_counts(x):
        if x <= root:
            return pi1_small[x], pi3_small[x]
        return pi1[x], int(x >= 3)

    def local_weight(p, e, good_local):
        if not good_local:
            return weights[e]
        residue = p % 3
        if residue == 0:
            return weights[e]
        if residue == 1:
            return weights[e] if (e + 1) % 3 else 0
        return weights[e] if e % 2 == 0 else 0

    def summatory(good_local):
        @lru_cache(maxsize=None)
        def F(x, first_idx):
            if x <= 1:
                return 1
            # Terms whose least prime is greater than sqrt(x) are prime numbers.
            prev = primes[first_idx - 1] if first_idx else 1
            cut = max(prev, isqrt(x))
            c1x, c3x = prime_counts(x)
            c1c, c3c = prime_counts(cut)
            if good_local:
                prime_sum = M * ((c1x - c1c) + (c3x - c3c))
            else:
                prime_sum = M * ((pi[x] - pi.get(cut, 0)) if cut > root else (pi[x] - pi.get(cut, 0)))
            ans = (1 + prime_sum) % MOD

            bound = isqrt(x)
            end = bisect_right(primes, bound)
            for idx in range(first_idx, end):
                p = primes[idx]
                power = p
                e = 1
                next_idx = idx + 1
                while power <= x:
                    coeff = local_weight(p, e, good_local)
                    if coeff:
                        ans += coeff * F(x // power, next_idx)
                        ans %= MOD
                    if power > x // p:
                        break
                    power *= p
                    e += 1
            return ans

        return F(N, 0)

    all_sum = summatory(False)
    bad_sum = summatory(True)
    return (all_sum - bad_sum) % MOD

