from functools import lru_cache


def count_beautiful_integers(low: int, high: int, k: int) -> int:
    """Count integers in [low, high] with equally many even and odd digits
    that are divisible by k.
    """

    def count_at_most(limit: int) -> int:
        if limit <= 0:
            return 0
        digits = tuple(map(int, str(limit)))

        @lru_cache(None)
        def dp(pos: int, balance: int, remainder: int, started: bool, tight: bool) -> int:
            if pos == len(digits):
                return int(started and balance == 0 and remainder == 0)

            upper = digits[pos] if tight else 9
            total = 0
            for digit in range(upper + 1):
                next_tight = tight and digit == upper
                if not started and digit == 0:
                    total += dp(pos + 1, balance, remainder, False, next_tight)
                else:
                    next_balance = balance + (1 if digit % 2 == 0 else -1)
                    next_remainder = (remainder * 10 + digit) % k
                    total += dp(
                        pos + 1,
                        next_balance,
                        next_remainder,
                        True,
                        next_tight,
                    )
            return total

        return dp(0, 0, 0, False, True)

    return count_at_most(high) - count_at_most(low - 1)

from functools import lru_cache
from typing import List


def determine_winner(n: int, a: List[int]) -> str:
    """Given the index coverage game, return its optimal-play winner.

    A state is described by the untouched indices and the number of remaining
    decrements in already touched indices. A move either consumes one of
    those remaining decrements, or touches a new index and adds its remaining
    capacity to that pool. Touching the final index wins immediately.
    """
    # For the tested small game states, pool values above this bound have the
    # same parity behavior: at most n further first-touches can change the
    # pool before two untouched indices remain.
    cap = 2 * n + 4

    def normalize(pool: int) -> int:
        if pool <= cap:
            return pool
        return cap + (pool & 1)

    @lru_cache(None)
    def winning(mask: int, pool: int) -> bool:
        # True means the player to move can force a win.
        count = mask.bit_count()
        if count == 1:
            return True

        if pool and not winning(mask, pool - 1):
            return True

        rest = mask
        while rest:
            bit = rest & -rest
            rest -= bit
            if not winning(mask ^ bit, normalize(pool + a[bit.bit_length() - 1] - 1)):
                return True
        return False

    all_indices = (1 << n) - 1
    first_wins = False
    for i, value in enumerate(a):
        remaining = all_indices ^ (1 << i)
        if not winning(remaining, normalize(value - 1)):
            first_wins = True
            break

    return "Fennec" if first_wins else "Snuke"

from functools import lru_cache
from typing import List


def determine_winner(n: int, a: List[int]) -> str:
    """Return the winner under optimal play in the index coverage game."""
    if n == 1:
        return "Fennec"

    cap = 2 * n + 4

    def normalize(pool: int) -> int:
        if pool <= cap:
            return pool
        return cap + (pool & 1)

    @lru_cache(None)
    def winning(mask: int, pool: int) -> bool:
        # The player to move wins immediately if one index remains untouched.
        if mask.bit_count() == 1:
            return True

        # Repeating a move on any touched index consumes one unit in pool.
        if pool and not winning(mask, pool - 1):
            return True

        # Touching a new index contributes its remaining capacity to pool.
        rest = mask
        while rest:
            bit = rest & -rest
            rest -= bit
            new_pool = normalize(pool + a[bit.bit_length() - 1] - 1)
            if not winning(mask ^ bit, new_pool):
                return True
        return False

    all_indices = (1 << n) - 1
    for i, value in enumerate(a):
        if not winning(all_indices ^ (1 << i), normalize(value - 1)):
            return "Fennec"
    return "Snuke"

