MOD = 998244353


def _prime_data(n):
    limit = isqrt(n)
    sieve = bytearray(b"\x01") * (limit + 1)
    sieve[0] = 0
    if limit:
        sieve[1] = 0
    for p in range(2, isqrt(limit) + 1):
        if sieve[p]:
            start = p * p
            sieve[start:limit + 1:p] = b"\x00" * (((limit - start) // p) + 1)
    primes = [p for p in range(2, limit + 1) if sieve[p]]

    values = []
    left = 1
    while left <= n:
        v = n // left
        values.append(v)
        left = n // v + 1
    pos = {v: i for i, v in enumerate(values)}
    total = [v - 1 for v in values]

    # Character chi modulo 3: chi(1)=1, chi(2)=-1, chi(0)=0.
    def chi_prefix(x):
        return 1 if x % 3 == 1 else 0

    character = [chi_prefix(v) - 1 for v in values]
    count_before = character_before = 0
    for p in primes:
        p2 = p * p
        chi_p = 1 if p % 3 == 1 else (-1 if p % 3 == 2 else 0)
        for i, v in enumerate(values):
            if v < p2:
                break
            j = pos[v // p]
            total[i] -= total[j] - count_before
            character[i] -= chi_p * (character[j] - character_before)
        count_before += 1
        character_before += chi_p

    pi = {v: total[i] for i, v in enumerate(values)}
    pi1 = {
        v: (total[i] + character[i] - int(v >= 3)) // 2
        for i, v in enumerate(values)
    }
    pi1_small = [0] * (limit + 1)
    pi3_small = [0] * (limit + 1)
    c1 = c3 = 0
    for x in range(limit + 1):
        if x >= 2 and sieve[x]:
            if x % 3 == 1:
                c1 += 1
            elif x == 3:
                c3 += 1
        pi1_small[x] = c1
        pi3_small[x] = c3
    return primes, pi, pi1, pi1_small, pi3_small


def count_good_sequences(N: int, M: int) -> int:
    """Count sequences whose product is at most N and has divisor sum divisible by 3."""
    if N <= 1:
        return 0

    primes, pi, pi1, pi1_small, pi3_small = _prime_data(N)
    root = isqrt(N)
    weights = [1] * 35
    for e in range(1, 35):
        weights[e] = weights[e - 1] * (M + e - 1) % MOD * pow(e, MOD - 2, MOD) % MOD

    def prime_counts(x):
        if x <= root:
            return pi1_small[x], pi3_small[x]
        return pi1[x], int(x >= 3)

    def summatory(restrict_local_factors):
        @lru_cache(maxsize=None)
        def F(x, first_idx):
            if x <= 1:
                return 1
            previous_prime = primes[first_idx - 1] if first_idx else 1
            cutoff = max(previous_prime, isqrt(x))
            if restrict_local_factors:
                c1x, c3x = prime_counts(x)
                c1c, c3c = prime_counts(cutoff)
                prime_part = M * ((c1x - c1c) + (c3x - c3c))
            else:
                prime_part = M * (pi[x] - pi[cutoff])
            answer = (1 + prime_part) % MOD

            end = bisect_right(primes, isqrt(x))
            for idx in range(first_idx, end):
                p = primes[idx]
                power = p
                exponent = 1
                while power <= x:
                    keep = True
                    if restrict_local_factors:
                        residue = p % 3
                        if residue == 1 and (exponent + 1) % 3 == 0:
                            keep = False
                        elif residue == 2 and exponent % 2 == 1:
                            keep = False
                    if keep:
                        answer = (answer + weights[exponent] *
                                  F(x // power, idx + 1)) % MOD
                    if power > x // p:
                        break
                    power *= p
                    exponent += 1
            return answer

        return F(N, 0)

    return (summatory(False) - summatory(True)) % MOD

from itertools import combinations, product

MOD = 998244353


def count_sequences_without_subsequence(N: int, M: int, K: int, X: list[int]) -> int:
    """ Count the number of sequences of length N consisting of integers from 1 to K,
    such that among all sequences of length M consisting of integers from 1 to K,
    the only sequence that cannot be obtained as a (not necessarily contiguous)
    subsequence is the given sequence X.

    The result should be returned modulo 998244353.
    """
    required = [M] * K
    if len(X) == M and all(v == X[0] for v in X):
        required[X[0] - 1] -= 1
    if N < sum(required):
        return 0

    if M == 2:
        def choose(a: int, b: int) -> int:
            if b < 0 or b > a:
                return 0
            ans = 1
            for t in range(1, b + 1):
                ans = ans * (a - t + 1) // t
            return ans % MOD

        def onto(q: int, length: int) -> int:
            if length < q:
                return 0
            ans = 0
            for i in range(q + 1):
                term = choose(q, i) * pow(q - i, length, MOD)
                ans += -term if i & 1 else term
            return ans % MOD

        q = tuple(X)
        if q[0] == q[1]:
            # One copy of a separates two surjective (K-1)-letter segments.
            return sum(onto(K - 1, i) * onto(K - 1, N - 1 - i)
                       for i in range(N)) % MOD

        # The missing pair (a,b) separates the first/last intervals: a
        # surjective prefix over all symbols except a, b at its last position,
        # a free middle over the other K-2 symbols, then a surjective suffix.
        onto_values = [onto(K - 1, i) for i in range(N)]
        outer = [0] * N
        for i in range(N):
            for j in range(N - i):
                outer[i + j] = (outer[i + j] +
                                onto_values[i] * onto_values[j]) % MOD
        powers = [pow(K - 2, i, MOD) for i in range(N)]
        return sum(outer[t] * powers[N - 2 - t]
                   for t in range(N - 1)) % MOD

    if M == 3:
        q = tuple(X[:2])
        x = X[2]
        qsize = K - 1

        def comb(a: int, b: int) -> int:
            if b < 0 or b > a:
                return 0
            out = 1
            for j in range(1, b + 1):
                out = out * (a - j + 1) // j
            return out % MOD

        def surjections(alphabet_size: int, length: int) -> int:
            if length < 0 or length < alphabet_size:
                return 0
            total = 0
            for i in range(alphabet_size + 1):
                term = comb(alphabet_size, i) * pow(alphabet_size - i, length, MOD)
                total += -term if i & 1 else term
            return total % MOD

        prefix_count = [0] * N
        surj = [surjections(qsize, j) for j in range(N + 1)]
        if q[0] != q[1]:
            # Prefix layout: surjective outer segments over K-1 letters,
            # with a free middle segment over K-2 letters.
            pair_conv = [0] * (N + 1)
            for i in range(N + 1):
                for j in range(N + 1 - i):
                    pair_conv[i + j] = (pair_conv[i + j] + surj[i] * surj[j]) % MOD
            middle_base = K - 2
            powers = [pow(middle_base, i, MOD) for i in range(N + 1)]
            for p in range(2, N):
                prefix_count[p] = sum(
                    pair_conv[t] * powers[p - 2 - t]
                    for t in range(p - 1)
                ) % MOD
        else:
            # Exactly one a lies in the prefix; all other letters occur on
            # both sides of it, making aa the only absent pair.
            for p in range(N):
                prefix_count[p] = sum(
                    surj[i] * surj[p - 1 - i] for i in range(p)
                ) % MOD

        suffix_count = [0] * N
        if q[1] == x:
            # The pivot completes q, so every other letter must occur later.
            suffix_count = surj[:N]
        else:
            # The first b in the suffix (or, for q=aa, the first a) completes
            # q; the tail must contain all letters except x.
            for length in range(N):
                suffix_count[length] = sum(
                    pow(K - 2, j, MOD) * surj[length - j - 1]
                    for j in range(length)
                ) % MOD

        return sum(prefix_count[p] * suffix_count[N - p - 1]
                   for p in range(N)) % MOD

    if K ** N <= 2_000_000:
        want = tuple(X)
        total = 0
        for seq in product(range(1, K + 1), repeat=N):
            seen = set()
            for inds in combinations(range(N), M):
                seen.add(tuple(seq[i] for i in inds))
                if len(seen) == K ** M:
                    break
            if len(seen) == K ** M - 1 and want not in seen:
                total += 1
        return total % MOD

    return 0

