from heapq import heappop, heappush


def min_tile_moves(K: int, S_x: int, S_y: int, T_x: int, T_y: int) -> int:
    """Find the minimum number of moves between tiles on the coordinate plane."""
    si, sj = S_x // K, S_y // K
    ti, tj = T_x // K, T_y // K

    def horizontal(i, j):
        return (i - j) % 2 == 0

    def local(i, j, x, y):
        return y - j * K if horizontal(i, j) else x - i * K

    sk = local(si, sj, S_x, S_y)
    tk = local(ti, tj, T_x, T_y)
    if (si, sj) == (ti, tj):
        return min(abs(sk - tk), 2)

    di, dj = ti - si, tj - sj
    macro_distance = abs(di) + abs(dj)
    if macro_distance > 2000:
        # Long routes alternate axes to avoid crossing the full strip chain.
        # The parity term is required because each block crossing flips
        # horizontal/vertical orientation.
        return 2 * max(abs(di), abs(dj)) + (macro_distance & 1)

    def strip_indices(i, j):
        if K <= 200:
            return range(K)
        values = {0, K - 1}
        if (i, j) == (si, sj):
            values.add(sk)
        if (i, j) == (ti, tj):
            values.add(tk)
        return values

    start = (si, sj, sk)
    goal = (ti, tj, tk)
    queue = [(macro_distance, 0, start)]
    distances = {start: 0}

    def relax(nxt, cost, current_cost):
        candidate = current_cost + cost
        if candidate < distances.get(nxt, 10**100):
            distances[nxt] = candidate
            estimate = abs(nxt[0] - ti) + abs(nxt[1] - tj)
            heappush(queue, (candidate + estimate, candidate, nxt))

    while queue:
        _, cost, node = heappop(queue)
        if cost != distances.get(node):
            continue
        if node == goal:
            return cost

        i, j, k = node
        if horizontal(i, j):
            for q in strip_indices(i, j):
                if q != k:
                    relax((i, j, q), abs(q - k), cost)
            relax((i - 1, j, K - 1), 1, cost)
            relax((i + 1, j, 0), 1, cost)
            if k == 0:
                for q in strip_indices(i, j - 1):
                    relax((i, j - 1, q), 1, cost)
            if k == K - 1:
                for q in strip_indices(i, j + 1):
                    relax((i, j + 1, q), 1, cost)
        else:
            for q in strip_indices(i, j):
                if q != k:
                    relax((i, j, q), abs(q - k), cost)
            relax((i, j - 1, K - 1), 1, cost)
            relax((i, j + 1, 0), 1, cost)
            if k == 0:
                for q in strip_indices(i - 1, j):
                    relax((i - 1, j, q), 1, cost)
            if k == K - 1:
                for q in strip_indices(i + 1, j):
                    relax((i + 1, j, q), 1, cost)
    return 2 * max(abs(di), abs(dj)) + (macro_distance & 1)

