    return (fact[n] * invfact[k] % MOD * invfact[n-k] - 1) % MOD


def _ending_inside(entries):
    n = len(entries)
    out = [0] * n
    total = sum(entries) % MOD
    for i in range(n):
        out[i] = total
        total = (total - entries[n - 1 - i]) % MOD
    return out


def count_paths(W: int, H: int, L: int, R: int, D: int, U: int) -> int:
    """Count monotone unit-step paths whose vertices avoid the rectangular hole."""
    if (W + 1) * (H + 1) <= 2_000_000:
        col = [0] * (W + 1)
        ans = 0
        for y in range(H + 1):
            left = 0
            for x in range(W + 1):
                if L <= x <= R and D <= y <= U:
                    col[x] = left = 0
                    continue
                cur = (1 + left + col[x]) % MOD
                ans = (ans + cur) % MOD
                col[x] = left = cur
        return ans

    limit = W + H + 2
    fact = [1] * (limit + 1)
    for i in range(1, limit + 1):
        fact[i] = fact[i - 1] * i % MOD
    invfact = [1] * (limit + 1)
    invfact[limit] = pow(fact[limit], MOD - 2, MOD)
    for i in range(limit, 0, -1):
        invfact[i-1] = invfact[i] * i % MOD

    full = _wb([W+1-i for i in range(W+1)],
               [H+1-i for i in range(H+1)], fact, invfact)
    w, h = R-L+1, U-D+1
    eb, el, lt, er = [0]*w, [0]*h, [0]*w, [0]*h

    if D:
        for i in range(w):
            eb[i] = _rect(L+i, D-1, fact, invfact)
    if L:
        if D:
            eb[0] = (eb[0] + _rect(L-1, D, fact, invfact)) % MOD
        else:
            el[0] = _rect(L-1, 0, fact, invfact)
        for j in range(1, h):
            el[j] = _rect(L-1, D+j, fact, invfact)

    if U < H:
        for i in range(w):
            lt[i] = _rect(W-L-i, H-U-1, fact, invfact)
    if R < W:
        if U < H:
            lt[-1] = (lt[-1] + _rect(W-R-1, U, fact, invfact)) % MOD
        for j in range(h):
            if j == h-1 and U < H:
                continue
            er[j] = _rect(W-R-1, H-D-j, fact, invfact)

    bad = 0
    if D and U < H:
        c = _conv(eb[::-1], lt)
        dy = U-D
        for dx in range(w):
            bad += c[w-1+dx] * fact[dx+dy] % MOD * invfact[dx] % MOD * invfact[dy]
    if L and R < W:
        c = _conv(el[::-1], er)
        dx = R-L
        for dy in range(h):
            bad += c[h-1+dy] * fact[dx+dy] % MOD * invfact[dx] % MOD * invfact[dy]
    if D and R < W:
        bad += _wb(eb[::-1], er, fact, invfact)
    if L and U < H:
        bad += _wb(lt, el[::-1], fact, invfact)

    sx = [max(0, min(R, W-dx)-L+1) for dx in range(W-L+1)]
    sy = [max(0, min(U, H-dy)-D+1) for dy in range(H-D+1)]
    bad += _wb(sx, sy, fact, invfact)

    bad += _wb(_ending_inside(eb), [1]*h, fact, invfact)
    bad += _wb([1]*w, _ending_inside(el), fact, invfact)
    return (full - bad) % MOD

MOD = 998244353
_ROOT = 3


def _ntt(a, inv):
    n = len(a)
    j = 0
    for i in range(1, n):
        bit = n >> 1
        while j & bit:
            j ^= bit
            bit >>= 1
        j ^= bit
        if i < j:
            a[i], a[j] = a[j], a[i]
    size = 2
    while size <= n:
        wlen = pow(_ROOT, (MOD - 1) // size, MOD)
        if inv:
            wlen = pow(wlen, MOD - 2, MOD)
        half = size // 2
        for start in range(0, n, size):
            w = 1
            for i in range(start, start + half):
                u = a[i]
                v = a[i + half] * w % MOD
                a[i] = (u + v) % MOD
                a[i + half] = (u - v) % MOD
                w = w * wlen % MOD
        size <<= 1
    if inv:
        ni = pow(n, MOD - 2, MOD)
        for i in range(n):
            a[i] = a[i] * ni % MOD


def _conv(a, b):
    if not a or not b:
        return []
    if len(a) * len(b) <= 4096:
        z = [0] * (len(a) + len(b) - 1)
        for i, x in enumerate(a):
            for j, y in enumerate(b):
                z[i+j] = (z[i+j] + x*y) % MOD
        return z
    need = len(a) + len(b) - 1
    n = 1
    while n < need:
        n <<= 1
    x = a + [0] * (n-len(a))
    y = b + [0] * (n-len(b))
    _ntt(x, False)
    _ntt(y, False)
    for i in range(n):
        x[i] = x[i] * y[i] % MOD
    _ntt(x, True)
    return x[:need]


def _wb(a, b, fact, invfact):
    x = [v * invfact[i] % MOD for i, v in enumerate(a)]
    y = [v * invfact[i] % MOD for i, v in enumerate(b)]
    c = _conv(x, y)
    return sum(v * fact[i] for i, v in enumerate(c)) % MOD


def _rect(x, y, fact, invfact):
    n, k = x+y+2, x+1
    return (fact[n] * invfact[k] % MOD * invfact[n-k] - 1) % MOD


def _prefix_total(x, y, fact, invfact):
    # Sum _rect(i,j) over 0<=i<=x, 0<=j<=y.
    if x < 0 or y < 0:
        return 0
    n, k = y+3, 2
    term = fact[n] * invfact[k] % MOD * invfact[n-k] % MOD
    total = 0
    for i in range(x+1):
        total = (total + term) % MOD
        term = term * (i+y+4) % MOD * fact[i+2] % MOD * invfact[i+3] % MOD
    return (total - (x+1)*(y+2)) % MOD


def _ending_inside(entries):
    n = len(entries)
    out = [0] * n
    total = sum(entries) % MOD
    for i in range(n):
        out[i] = total
        total = (total - entries[n-1-i]) % MOD
    return out


def count_paths(W: int, H: int, L: int, R: int, D: int, U: int) -> int:
    """Count monotone unit-step paths whose vertices avoid the rectangular hole."""
    if (W+1)*(H+1) <= 2_000_000:
        col = [0]*(W+1)
        ans = 0
        for y in range(H+1):
            left = 0
            for x in range(W+1):
                if L <= x <= R and D <= y <= U:
                    col[x] = left = 0
                    continue
                cur = (1+left+col[x]) % MOD
                ans = (ans+cur) % MOD
                col[x] = left = cur
        return ans

    limit = W+H+4
    fact = [1]*(limit+1)
    for i in range(1, limit+1):
        fact[i] = fact[i-1]*i % MOD
    invfact = [1]*(limit+1)
    invfact[limit] = pow(fact[limit], MOD-2, MOD)
    for i in range(limit, 0, -1):
        invfact[i-1] = invfact[i]*i % MOD

    full = _prefix_total(W, H, fact, invfact)
    w, h = R-L+1, U-D+1
    eb, el, lt, er = [0]*w, [0]*h, [0]*w, [0]*h
    if D:
        for i in range(w):
            eb[i] = _rect(L+i, D-1, fact, invfact)
    if L:
        if D:
            eb[0] = (eb[0] + _rect(L-1, D, fact, invfact)) % MOD
        else:
            el[0] = _rect(L-1, 0, fact, invfact)
        for j in range(1, h):
            el[j] = _rect(L-1, D+j, fact, invfact)
    if U < H:
        for i in range(w):
            lt[i] = _rect(W-L-i, H-U-1, fact, invfact)
    if R < W:
        if U < H:
            lt[-1] = (lt[-1] + _rect(W-R-1, U, fact, invfact)) % MOD
        for j in range(h):
            if j == h-1 and U < H:
                continue
            er[j] = _rect(W-R-1, H-D-j, fact, invfact)

    bad = 0
    if D and U < H:
        c = _conv(eb[::-1], lt)
        dy = U-D
        for dx in range(w):
            bad += c[w-1+dx] * fact[dx+dy] % MOD * invfact[dx] % MOD * invfact[dy]
    if L and R < W:
        c = _conv(el[::-1], er)
        dx = R-L
        for dy in range(h):
            bad += c[h-1+dy] * fact[dx+dy] % MOD * invfact[dx] % MOD * invfact[dy]
    if D and R < W:
        bad += _wb(eb[::-1], er, fact, invfact)
    if L and U < H:
        bad += _wb(lt, el[::-1], fact, invfact)

    # All paths starting in the hole.
    sx0, sx1 = W-R, W-L
    sy0, sy1 = H-U, H-D
    starts = (_prefix_total(sx1, sy1, fact, invfact)
              - _prefix_total(sx0-1, sy1, fact, invfact)
              - _prefix_total(sx1, sy0-1, fact, invfact)
              + _prefix_total(sx0-1, sy0-1, fact, invfact)) % MOD
    bad += starts

    bad += _wb(_ending_inside(eb), [1]*h, fact, invfact)
    bad += _wb([1]*w, _ending_inside(el), fact, invfact)
    return (full-bad) % MOD

